async function renderOutput(){if(!image)throw Error('Open an image first.');const w=enhance?Math.round(image.width*+read('scale')):num('width',{min:1,max:16384}),h=enhance?Math.round(image.height*+read('scale')):num('height',{min:1,max:16384});pixelLimit(w,h);const c=el('canvas',{width:w,height:h}),ctx=c.getContext('2d');ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';if(enhance){ctx.filter=`contrast(${num('contrast',{min:0,max:300})}%) saturate(${num('saturation',{min:0,max:300})}%)`;ctx.drawImage(image,0,0,w,h);return c}if(read('format')==='image/jpeg'){ctx.fillStyle='white';ctx.fillRect(0,0,w,h)}let source=image,temp=null;const sx=(crop?.x||0)*image.width,sy=(crop?.y||0)*image.height,sw=(crop?.w||1)*image.width,sh=(crop?.h||1)*image.height,rotation=+read('rotation');const maxSource=mobile()?8e6:24e6,s=Math.min(1,Math.sqrt(maxSource/(sw*sh))),rw=Math.max(1,Math.round(sw*s)),rh=Math.max(1,Math.round(sh*s));temp=el('canvas',{width:rotation%180?rh:rw,height:rotation%180?rw:rh});const tc=temp.getContext('2d');tc.translate(temp.width/2,temp.height/2);tc.rotate(rotation*Math.PI/180);tc.scale($('#flip-x').checked?-1:1,$('#flip-y').checked?-1:1);tc.drawImage(image,sx,sy,sw,sh,-rw/2,-rh/2,rw,rh);source=temp;ctx.filter=`brightness(${num('brightness',{min:0,max:300})}%) contrast(${num('contrast',{min:0,max:300})}%)`;fittedDraw(ctx,source,w,h,read('fit'),read('position'));ctx.filter='none';watermark(ctx,read('watermark'),w,h);temp.width=temp.height=0;return c}
